#include <stdio.h>

typedef struct { const char *kind; int hp; } Enemy;

void split_kg(int total, int people, int *each, int *left)
{
    *each = total / people;
    *left = total % people;
}

Enemy *first_alive(Enemy *list, int n)
{
    for (int i = 0; i < n; i++)
        if (list[i].hp > 0) return &list[i];
    return NULL;
}

int main(void)
{
    int each, left;
    split_kg(17, 5, &each, &left);
    printf("each gets %d kg, %d kg left over\n", each, left);

    Enemy wave[3] = {{"slime", 0}, {"bat", 6}, {"wolf", 12}};
    Enemy *target = first_alive(wave, 3);
    if (target != NULL) {
        target->hp -= 4;
        printf("hit the %s, %d hp left\n", target->kind, target->hp);
    }
    printf("wave[1].hp is now %d\n", wave[1].hp);
    return 0;
}

