#include <stdlib.h>

typedef struct { const char *name; int hp; int max_hp; } Player;

int heal(Player *p, int amount)
{
    if (p == NULL || amount <= 0) return 0;
    int before = p->hp;
    p->hp += amount;
    if (p->hp > p->max_hp) p->hp = p->max_hp;
    return p->hp - before;
}

