exercises.solution:
#include <stdlib.h>

typedef struct { const char *kind; int hp; } Enemy;

Enemy *weakest(Enemy *list, int n)
{
    Enemy *best = NULL;
    for (int i = 0; i < n; i++) {
        if (list[i].hp <= 0) continue;        /* dead enemies don't count */
        if (best == NULL || list[i].hp < best->hp) best = &list[i];
    }
    return best;
}
